  function renderAll(){renderHome();const h=$('#home'),rs=reminders();h.insertAdjacentHTML('afterbegin',`<div class="quick-actions"><button class="quick-action" data-quick="patient"><span>➕</span>Neuer Patient</button><button class="quick-action" data-quick="material"><span>📦</span>Material buchen</button><button class="quick-action" data-quick="tour"><span>🚗</span>Tour starten</button><button class="quick-action" data-view="reports"><span>📋</span>Tagesbericht</button><button class="quick-action" data-view="dashboard"><span>📊</span>Dashboard</button><button class="quick-action" data-view="settings"><span>⚙</span>Einstellungen</button></div>${rs.length?`<div class="reminders">${rs.map(x=>`<div class="reminder">${x}</div>`).join('')}</div>`:''}`);h.addEventListener('click',e=>{if(e.target.closest('[data-quick="patient"]'))openPatient();if(e.target.closest('[data-quick="material"]'))openQuickMaterial();if(e.target.closest('[data-quick="tour"]')){state.tourStartedAt??=Date.now();save('Tour gestartet');renderAll()}});renderPlan();renderPatients();renderMaterials();renderTodayMaterials();renderReports();renderStats();renderWeek();renderCalendar();renderInventory();renderSettings();renderWorktime();renderDashboard()}
  function openQuickMaterial(){$('#modalContent').innerHTML=`<form id="quickMaterial" class="modal-inner modal-form"><h2>Material buchen</h2><div class="material-use">${state.materials.filter(m=>!m.archived).map(m=>`<label><input type="checkbox" name="m" value="${esc(m.name)}"> ${esc(m.name)}</label>`).join('')}</div><div class="modal-actions"><button type="button" id="closeModal" class="btn secondary">Abbrechen</button><button class="btn">Buchen</button></div></form>`;const d=$('#modal');d.showModal();$('#closeModal').onclick=()=>d.close();$('#quickMaterial').onsubmit=e=>{e.preventDefault();new FormData(e.target).getAll('m').forEach(name=>state.materialBookings.push({at:Date.now(),name}));save('Material gebucht');d.close();renderAll();toast('Material gebucht')}}
  function ask(q){const chat=$('#pilotChat');chat.insertAdjacentHTML('beforeend',`<div class="chat-message user">${esc(q)}</div>`);const n=normal(q),p=patientFromText(q);let a='Ich helfe gerne bei Tour, Patienten, Material, Arbeitszeit und Berichten.';if(/pause.*begin|beginnepause/.test(n)){if(!state.pauseLog.at(-1)||state.pauseLog.at(-1).end)state.pauseLog.push({start:Date.now()});save('Pause via PflegePilot');renderAll();a='Ihre Pause hat begonnen.'}else if(/pause.*ende|beendepause/.test(n)){if(state.pauseLog.at(-1)&&!state.pauseLog.at(-1).end)state.pauseLog.at(-1).end=Date.now();save('Pause via PflegePilot');renderAll();a='Ihre Pause ist beendet.'}else if(/wievielepatienten.*heute/.test(n))a=`Heute haben Sie ${active().filter(p=>!p.archived).length} Patienten geplant.`;else if(/welchetour.*morgen/.test(n)){const d=new Date();d.setDate(d.getDate()+1);a=`Morgen geplant: ${(state.weekPlans[key(d)]||[]).map(id=>state.patients.find(p=>p.id===id)?.name).filter(Boolean).join(', ')||'noch keine Patienten'}.`}else if(/welchesmaterialfehlt/.test(n)){const x=state.materials.filter(m=>m.minimum>0&&m.stock<=m.minimum);a=x.length?`Knappes Material: ${x.map(m=>m.name).join(', ')}.`:'Aktuell ist kein Material knapp.'}else if(/wie.*unterwegs|fahrzeit/.test(n))a=`Ihre berechnete Fahrzeit heute beträgt ${fmt(driveSeconds())}.`;else if(/kilometer/.test(n))a=`Heute: ${Number(state.kilometers||0).toFixed(1)} km. Woche: ${Object.values(state.kilometerLog).reduce((s,x)=>s+Number(x),0).toFixed(1)} km.`;else if(/bericht/.test(n)){show('reports');a='Der Tagesbericht ist geöffnet.'}else if(/offne|oeffne|zeige/.test(n)&&p){openPatient(p);a=`Ich öffne ${p.name}.`}else if(/material.*verwendet/.test(n))a=`Heute verwendet: ${Object.entries(used()).map(([x,c])=>`${c} × ${x}`).join(', ')||'noch keines'}.`;else if(/patientenfehlen/.test(n))a=`Noch offen: ${active().filter(p=>p.status!=='done'&&!p.archived).map(p=>p.name).join(', ')||'keine'}.`;chat.insertAdjacentHTML('beforeend',`<div class="chat-message">${esc(a)}</div>`);chat.scrollTop=chat.scrollHeight}
  function setup(){const nav=[['home','⌂','Übersicht'],['dashboard','▦','Dashboard'],['dayplan','▣','Tour'],['worktime','◷','Arbeitszeit'],['week','▦','Woche'],['calendar','▤','Kalender'],['patients','♙','Patienten'],['materials','▤','Material'],['inventory','📦','Lager'],['reports','📋','Bericht'],['statistics','◔','Statistik'],['settings','⚙','Einstellungen']];$('#nav').innerHTML=nav.map(([id,i,t],n)=>`<button class="nav-item ${n?'':'active'}" data-view="${id}">${i} <span>${t}</span></button>`).join('');$('#mobileNav').innerHTML=nav.slice(0,5).map(([id,i,t],n)=>`<button data-view="${id}" class="${n?'':'active'}"><span>${i}</span><span>${t}</span></button>`).join('');document.addEventListener('click',e=>{const b=e.target.closest('[data-view]');if(b)show(b.dataset.view);if(e.target.id==='homeTheme'||e.target.id==='themeToggle'){state.theme=document.body.classList.contains('dark')?'light':'dark';theme();save('Darstellung geändert')}if(e.target.id==='openPilot')pilotOpen();if(e.target.matches('[data-open]')){openPatient(state.patients.find(p=>p.id===e.target.closest('[data-open]').dataset.open));$('#searchResults').hidden=true}if(e.target.id==='tourToggle'){if(state.tourStartedAt){state.workOffset=secs();state.tourStartedAt=null;toast('Tour beendet')}else{state.tourStartedAt=Date.now();toast('Tour gestartet')}save('Tourstatus geändert');renderAll()}});$('#globalSearch').oninput=e=>globalSearch(e.target.value);document.addEventListener('keydown',e=>{if((e.metaKey||e.ctrlKey)&&e.key.toLowerCase()==='k'){e.preventDefault();$('#globalSearch').focus()}})}
  function renderWorktime(){const paused=state.pauseLog.at(-1)&&!state.pauseLog.at(-1).end;$('#worktime').innerHTML=`<div class="page-head"><div><p class="eyebrow">Arbeitszeiterfassung</p><h1>Arbeitszeit</h1><p>Alle Zeiten werden lokal erfasst.</p></div><button id="pauseToggle" class="btn">${paused?'▶ Pause beenden':'Ⅱ Pause beginnen'}</button></div><div class="time-hero"><div><p>Gesamtarbeitszeit heute</p><div class="big-time work-time">${fmt(secs()-pauseSeconds())}</div><p>${state.tourStartedAt?'Arbeitsbeginn: '+new Date(state.tourStartedAt).toLocaleTimeString('de-DE',{hour:'2-digit',minute:'2-digit'}):'Tour noch nicht gestartet'}</p></div><button id="workTour" class="btn">${state.tourStartedAt?'■ Arbeit beenden':'▶ Arbeit beginnen'}</button></div><div class="grid metrics" style="margin-top:20px"><article class="metric"><div class="metric-top"><span>Besuchszeit</span><span>🩺</span></div><strong>${fmt(visitSeconds())}</strong><small>heute</small></article><article class="metric"><div class="metric-top"><span>Fahrzeit</span><span>🚗</span></div><strong>${fmt(driveSeconds())}</strong><small>berechnet</small></article><article class="metric"><div class="metric-top"><span>Pausenzeit</span><span>☕</span></div><strong>${fmt(pauseSeconds())}</strong><small>${paused?'läuft':'heute'}</small></article></div>`;$('#pauseToggle').onclick=()=>{if(paused){state.pauseLog.at(-1).end=Date.now();toast('Pause beendet')}else{state.pauseLog.push({start:Date.now()});toast('Pause gestartet')}save('Pause aktualisiert');renderWorktime()};$('#workTour').onclick=()=>{if(state.tourStartedAt){state.workOffset=secs();state.tourStartedAt=null;toast('Arbeit beendet')}else{state.tourStartedAt=Date.now();toast('Arbeit begonnen')}save('Arbeitszeit geändert');renderAll()}}
  function renderMaterials(){const visible=state.materials.filter(m=>state.showArchivedMaterials?true:!m.archived),shown=visible.slice(0,(state.materialPage||1)*200);const backPatient=materialsBackTarget?state.patients.find(x=>x.id===materialsBackTarget):null;$('#materials').innerHTML=`${backPatient?`<button type="button" id="backToPatientBtn" class="back-pill">← Zurück zu ${esc(backPatient.name)}</button>`:''}<div class="page-head"><div><p class="eyebrow">Lagerverwaltung</p><h1>Material</h1><p>${visible.length} Artikel sichtbar.</p></div><button id="addMaterial" class="btn">＋ Material hinzufügen</button></div><div class="panel"><div class="archive-toggle"><input id="archiveMaterialToggle" type="checkbox" ${state.showArchivedMaterials?'checked':''}><label for="archiveMaterialToggle">Archiviertes Material anzeigen</label></div><div class="filter-bar"><input id="materialSearch" placeholder="Material suchen …"></div><div id="materialsList" class="material-list">${shown.map(m=>`<div class="material-item" data-id="${m.id}"><b>${esc(m.name)} ${m.archived?'<span class="badge">Archiv</span>':''}</b><div class="row-actions"><button class="small-btn edit-m">Bearbeiten</button><button class="small-btn archive-m">${m.archived?'Aktivieren':'Archivieren'}</button><button class="small-btn danger delete-m">Löschen</button></div></div>`).join('')}</div></div>`;$('#backToPatientBtn')?.addEventListener('click',()=>openPatient(backPatient));$('#addMaterial').onclick=()=>openMaterial();$('#archiveMaterialToggle').onchange=e=>{state.showArchivedMaterials=e.target.checked;renderMaterials()};$('#materialSearch').oninput=e=>filterRows($('#materialsList'),e.target.value);$('#materialsList').onclick=e=>{const row=e.target.closest('[data-id]');if(!row)return;const m=state.materials.find(x=>x.id===row.dataset.id);if(e.target.matches('.edit-m'))openMaterial(m);if(e.target.matches('.archive-m')){m.archived=!m.archived;save('Material archiviert');renderAll();toast(m.archived?'Material archiviert':'Material aktiviert')}if(e.target.matches('.delete-m')&&confirm(`„${m.name}“ wirklich löschen?`)){state.materials=state.materials.filter(x=>x.id!==m.id);save('Material gelöscht');renderAll()}}}
  function renderSettings(){const s=state.settings;$('#settings').innerHTML=`<div class="page-head"><div><p class="eyebrow">App-Konfiguration</p><h1>Einstellungen</h1><p>Alle Daten bleiben lokal auf diesem Gerät.</p></div></div><div class="panel"><form id="settingsForm" class="form-grid"><label>Name der Pflegekraft<input name="caregiver" value="${esc(s.caregiver)}"></label><label>Firmenname<input name="company" value="${esc(s.company)}"></label><label>Sprache<select name="language" class="select"><option ${s.language==='Deutsch'?'selected':''}>Deutsch</option><option ${s.language==='English'?'selected':''}>English</option></select></label><label><input name="dark" type="checkbox" ${state.theme==='dark'?'checked':''}> Dunkelmodus</label><label><input name="autoBackup" type="checkbox" ${s.autoBackup?'checked':''}> Automatische Backups</label><label><input name="autoRelease" type="checkbox" ${s.autoRelease?'checked':''}> Automatische Releases</label><div class="full report-actions"><button class="btn">Einstellungen speichern</button><button type="button" id="dataExport" class="btn secondary">JSON exportieren</button><label class="btn secondary" style="cursor:pointer">Daten importieren<input id="dataImport" type="file" accept="application/json" hidden></label></div></form></div><div class="panel" style="margin-top:20px"><h2>Lokale Sicherungen</h2><div class="filter-bar"><select id="backupPick" class="select">${state.backups.map((b,i)=>`<option value="${i}">${new Date(b.at).toLocaleString('de-DE')} – ${esc(b.reason)}</option>`).join('')||'<option>Keine Sicherung verfügbar</option>'}</select><button id="restoreBackup" class="btn secondary">Backup wiederherstellen</button></div></div><div class="panel" style="margin-top:20px"><h2>Team &amp; Tourenaustausch</h2><p>Damit die Chefin Patienten zuteilen kann, ohne dass Daten über einen Server laufen: Alle Beteiligten tragen hier dasselbe Codewort ein – bitte persönlich oder telefonisch absprechen, <b>nicht</b> über denselben Kanal wie die Tour selbst.</p><form id="teamForm" class="form-grid"><label>Name Fachkraft 1<input name="teamMemberA" value="${esc(s.teamMemberA||'Fachkraft 1')}"></label><label>Name Fachkraft 2<input name="teamMemberB" value="${esc(s.teamMemberB||'Fachkraft 2')}"></label><label class="full">Team-Codewort<input name="teamPassphrase" value="${esc(s.teamPassphrase||'')}" placeholder="z. B. drei zufällige Wörter"></label><div class="full report-actions"><button class="btn secondary">Team-Einstellungen speichern</button><button type="button" id="openTourReceive" class="btn secondary">📥 Tour empfangen</button></div></form></div>`;$('#settingsForm').onsubmit=e=>{e.preventDefault();const f=new FormData(e.target);Object.assign(s,{caregiver:f.get('caregiver').trim(),company:f.get('company').trim(),language:f.get('language'),autoBackup:f.has('autoBackup'),autoRelease:f.has('autoRelease')});state.theme=f.has('dark')?'dark':'light';save('Einstellungen gespeichert');theme();toast('Einstellungen gespeichert')};$('#dataExport').onclick=()=>download('FiaMed-lokale-Daten.json',JSON.stringify(state,null,2),'application/json');$('#dataImport').onchange=e=>{const f=e.target.files[0];if(!f)return;const r=new FileReader();r.onload=()=>{try{const data=JSON.parse(r.result);if(!data.patients||!data.materials)throw Error();if(!confirm('Alle aktuell gespeicherten Daten durch diese Datei ersetzen? Das kann nicht rückgängig gemacht werden.'))return;state=data;upgradeState();renderAll();toast('Daten importiert')}catch{toast('Ungültige Sicherungsdatei.')}};r.readAsText(f)};$('#restoreBackup').onclick=()=>{const b=state.backups[Number($('#backupPick').value)];if(b&&confirm('Dieses lokale Backup wiederherstellen?')){state=b.snapshot;upgradeState();renderAll();toast('Backup wiederhergestellt')}};$('#teamForm').onsubmit=e=>{e.preventDefault();const f=new FormData(e.target);Object.assign(s,{teamMemberA:f.get('teamMemberA').trim()||'Fachkraft 1',teamMemberB:f.get('teamMemberB').trim()||'Fachkraft 2',teamPassphrase:f.get('teamPassphrase').trim()});save('Team-Einstellungen gespeichert');toast('Team-Einstellungen gespeichert')};$('#openTourReceive').onclick=openTourReceive}
  function save(reason='Änderung'){const snap=JSON.parse(JSON.stringify({...state,backups:[]}));state.backups??=[];state.backups.unshift({at:Date.now(),reason,snapshot:snap});localStorage.setItem(KEY,JSON.stringify(state))}
  function recurringForToday(p,d=new Date()){const r=p.recurrence||'none',wd=['sonntags','montags','dienstags','mittwochs','donnerstags','freitags','samstags'][d.getDay()];if(r==='daily'||r===wd)return true;if(r==='custom')return (p.recurrenceDays||[]).includes(wd);if(r==='twoDays'){const a=new Date(p.recurrenceAnchor||d);return Math.abs(Math.floor((new Date(d).setHours(0,0,0,0)-new Date(a).setHours(0,0,0,0))/86400000))%2===0}return false}
  function upgradeState(){state.weekPlans??={};state.calendarEvents??=[];state.settings??={caregiver:'',company:'FiaMed',language:'Deutsch',autoBackup:true,autoRelease:false,logo:''};state.settings.teamMemberA??='Fachkraft 1';state.settings.teamMemberB??='Fachkraft 2';state.settings.teamPassphrase??='';state.kilometerLog??={};state.pauseLog??=[];state.materialBookings??=[];state.dayClosed??=false;state.patients.forEach(p=>{p.visits??=[];p.archived??=false;p.favorite??=false;p.recurrence??='none';p.recurrenceAnchor??=key();p.dailyNote??='';p.nextHint??='';p.photo??='';p.materials??=[]});state.materials.forEach(m=>{m.stock??=0;m.minimum??=0;m.archived??=false;m.favorite??=false});save('Sicherungsstand vor Erweiterung')}
  function renderPlan(){const suggestions=state.patients.filter(p=>!p.archived&&recurringForToday(p)&&!p.selected);const list=active().filter(p=>!p.archived).sort((a,b)=>a.order-b.order);$('#dayplan').innerHTML=`<div class="page-head"><div><p class="eyebrow">Tourplanung</p><h1>Ihre Tour für heute</h1><p>Reihenfolge per Drag & Drop ändern – automatisch gespeichert.</p></div><div class="row-actions"><button id="sortPriority" class="btn secondary">Priorität</button><button id="sortDistance" class="btn secondary">Entfernung</button></div></div>${suggestions.length?`<div class="recurring-suggestions"><b>🔁 Vorschläge aus wiederkehrenden Besuchen</b><p>${suggestions.map(p=>esc(p.name)).join(', ')}</p><button id="addRecurring" class="small-btn">Alle zur Tour hinzufügen</button></div>`:''}<div class="plan-grid"><div class="panel"><div class="section-head"><h2>Reihenfolge der Tour</h2><span class="status open">${list.length} Patienten</span></div><div id="tourList" class="patient-list">${list.map(p=>`<div class="patient-row drag-row" draggable="true" data-id="${p.id}"><span class="drag-handle">⠿</span><span class="priority ${p.priority}"></span><span class="avatar">${initials(p.name)}</span><div class="patient-info"><b>${p.favorite?'★ ':''}${esc(p.name)}</b><small>${esc(p.address||'Keine Adresse')}</small></div><span class="status ${p.status}">${status(p.status)}</span></div>`).join('')||'<div class="empty">Keine Patienten ausgewählt.</div>'}</div></div><aside class="panel"><h2>Kilometer</h2><input id="kmInput" type="number" min="0" step="0.1" value="${state.kilometers||0}" style="width:100%"><button id="saveKm" class="small-btn" style="margin-top:8px">Speichern</button></aside></div>`;$('#addRecurring')?.addEventListener('click',()=>{suggestions.forEach(p=>p.selected=true);save('Wiederkehrende Besuche übernommen');renderAll();toast('Vorschläge zur Tour hinzugefügt')});let drag=null,tl=$('#tourList');tl.ondragstart=e=>{drag=e.target.closest('[data-id]');drag?.classList.add('dragging')};tl.ondragover=e=>{e.preventDefault();const t=e.target.closest('[data-id]');if(t&&drag&&t!==drag){const r=t.getBoundingClientRect();tl.insertBefore(drag,e.clientY<r.top+r.height/2?t:t.nextSibling)}};tl.ondragend=()=>{if(drag){[...tl.querySelectorAll('[data-id]')].forEach((x,i)=>state.patients.find(p=>p.id===x.dataset.id).order=i);save('Tourreihenfolge geändert');drag=null}};const order=fn=>{list.sort(fn).forEach((p,i)=>p.order=i);save('Tour sortiert');renderPlan()};$('#sortPriority').onclick=()=>order(sort);$('#sortDistance').onclick=()=>order((a,b)=>(a.address||'').localeCompare(b.address||''));$('#endTourNow').onclick=()=>showTourSummary();$('#saveKm').onclick=()=>{state.kilometers=Number($('#kmInput').value)||0;state.kilometerLog[key()]=state.kilometers;save('Kilometer aktualisiert');renderAll()}}
  function openPatient(p){const fresh=!p;p=p||{id:uid(),name:'',address:'',phone:'',notes:'',dailyNote:'',nextHint:'',materials:[],priority:'normal',selected:false,status:'open',visit:null,visits:[],favorite:false,recurrence:'none',recurrenceDays:[],birthDate:'',insurance:'',insuranceNumber:'',customFields:[],order:state.patients.length};p.recurrenceDays=p.recurrenceDays||[];p.customFields=p.customFields||[];const v=p.visit,quick=p.materials||[],hist=[...(p.visits||[])].sort((a,b)=>b.start-a.start).slice(0,30);const material=(arr,title)=>`<div class="material-use"><b>${title}</b><div>${arr.map(n=>`<label><input type="checkbox" name="used" value="${esc(n)}" ${(v?.used||[]).includes(n)?'checked':''}> ${esc(n)}</label>`).join('')||'Keine Auswahl'}</div></div>`;const weekDays=[['montags','Mo'],['dienstags','Di'],['mittwochs','Mi'],['donnerstags','Do'],['freitags','Fr'],['samstags','Sa'],['sonntags','So']];const recurrenceOptions=[['none','Nicht wiederkehrend'],['daily','täglich'],['twoDays','alle 2 Tage'],['montags','montags'],['dienstags','dienstags'],['mittwochs','mittwochs'],['donnerstags','donnerstags'],['freitags','freitags'],['samstags','samstags'],['sonntags','sonntags'],['custom','bestimmte Wochentage']];const customFieldsHtml=()=>p.customFields.map(c=>`<div class="custom-row"><input class="cf-label" placeholder="Thema" value="${esc(c.label||'')}"><textarea class="cf-text" placeholder="Was ist wichtig?">${esc(c.text||'')}</textarea><button type="button" class="remove-btn cf-remove" aria-label="Entfernen">✕</button></div>`).join('');$('#modalContent').innerHTML=`<form id="patientForm" class="modal-inner modal-form"><div class="section-head"><div class="name-row"><h2>${fresh?'Patient hinzufügen':esc(p.name)}</h2>${fresh?'':'<button type="button" class="info-btn" id="toggleInfo" aria-label="Mehr Infos" title="Mehr Infos">ⓘ</button><button type="button" class="icon-btn2" id="toMaterials" aria-label="Zur Materialverwaltung" title="Zur Materialverwaltung">📦</button>'}</div><span class="status ${p.status}">${status(p.status)||'Neu'}</span></div>${p.favorite?'<span class="favorite">★ Favorit</span>':''}<div id="mainPage" class="patient-page"><div class="form-grid"><label class="full">Name<input required name="name" value="${esc(p.name)}"></label><label>Adresse<input name="address" value="${esc(p.address)}"></label><label>Telefon<input name="phone" value="${esc(p.phone)}"></label><label>Wiederkehrender Besuch<select name="recurrence" id="recurrenceSelect" class="select">${recurrenceOptions.map(x=>`<option value="${x[0]}" ${p.recurrence===x[0]?'selected':''}>${x[1]}</option>`).join('')}</select></label><div class="full day-picker-wrap" id="dayPickerWrap" style="${p.recurrence==='custom'?'':'display:none'}"><div class="day-picker" id="dayPicker">${weekDays.map(x=>`<button type="button" class="day-btn ${p.recurrenceDays.includes(x[0])?'on':''}" data-d="${x[0]}">${x[1]}</button>`).join('')}</div></div><label class="full"><input type="checkbox" name="favorite" ${p.favorite?'checked':''}> Als Favorit markieren</label><label class="full">Allgemeine Notizen<textarea name="notes">${esc(p.notes)}</textarea></label><label class="full">Tagesnotiz<textarea name="dailyNote">${esc(p.dailyNote)}</textarea></label><label class="full">Hinweise für den nächsten Besuch<textarea name="nextHint">${esc(p.nextHint)}</textarea></label>${v?`${material(quick,'Schnellauswahl – häufig bei diesem Patienten')}${material(state.materials.filter(m=>!m.archived).map(m=>m.name),'Weitere Materialien')}`:''}<div class="full"><b>Patientenchronik</b><div class="history">${hist.map(x=>`<div class="history-item"><b>${new Date(x.start).toLocaleString('de-DE')} · ${fmt(x.duration)}</b>${esc((x.used||[]).join(', ')||'Kein Material')}<br>${esc(x.note||p.notes||'')}</div>`).join('')||'<div class="history-item">Noch keine Besuche dokumentiert.</div>'}</div></div></div><div class="visit-controls">${!fresh&&p.status==='open'?'<button type="button" class="btn" id="startVisit">📍 Ich bin da</button>':''}${!fresh&&p.status==='active'?'<button type="button" class="btn" id="endVisit">✅ Besuch beenden</button>':''}${!fresh?'<button type="button" class="btn secondary" id="navPatient">📍 Navigation</button><button type="button" class="btn secondary" id="callPatient">📞 Anrufen</button>':''}</div></div><div id="infoPage" class="patient-page" style="display:none"><button type="button" class="back-pill" id="backToMain">← Zurück</button><div class="form-grid"><label>Geburtsdatum<input type="date" name="birthDate" value="${esc(p.birthDate)}"></label><label>Krankenkasse<input name="insurance" value="${esc(p.insurance)}"></label><label>Versicherungsnummer<input name="insuranceNumber" value="${esc(p.insuranceNumber)}"></label></div><div class="custom-list" id="customList">${customFieldsHtml()}</div><button type="button" class="add-custom" id="addCustom">＋ Eigene Angabe hinzufügen</button></div><div class="modal-actions"><button type="button" id="closeModal" class="btn secondary">Schließen</button><button class="btn">Speichern</button></div></form>`;const d=$('#modal');d.showModal();$('#closeModal').onclick=()=>d.close();$('#startVisit')?.addEventListener('click',()=>{d.close();startVisit(p)});$('#endVisit')?.addEventListener('click',()=>{p.visit.used=[...new Set(new FormData($('#patientForm')).getAll('used'))];d.close();endVisit(p)});$('#navPatient')?.addEventListener('click',()=>navigate(p));$('#callPatient')?.addEventListener('click',()=>p.phone?location.href=`tel:${p.phone}`:toast('Keine Telefonnummer hinterlegt.'));const mainPage=$('#mainPage'),infoPage=$('#infoPage'),toggleInfo=$('#toggleInfo'),backToMain=$('#backToMain');toggleInfo?.addEventListener('click',()=>{mainPage.style.display='none';infoPage.style.display='';toggleInfo.classList.add('open')});backToMain?.addEventListener('click',()=>{infoPage.style.display='none';mainPage.style.display='';toggleInfo?.classList.remove('open')});$('#recurrenceSelect').addEventListener('change',e=>{$('#dayPickerWrap').style.display=e.target.value==='custom'?'':'none'});$('#dayPicker')?.addEventListener('click',e=>{const b=e.target.closest('.day-btn');if(b)b.classList.toggle('on')});$('#addCustom')?.addEventListener('click',()=>{const row=document.createElement('div');row.className='custom-row';row.innerHTML='<input class="cf-label" placeholder="Thema"><textarea class="cf-text" placeholder="Was ist wichtig?"></textarea><button type="button" class="remove-btn cf-remove" aria-label="Entfernen">✕</button>';$('#customList').appendChild(row)});$('#customList')?.addEventListener('click',e=>{if(e.target.closest('.cf-remove'))e.target.closest('.custom-row').remove()});$('#toMaterials')?.addEventListener('click',()=>{materialsBackTarget=p.id;d.close();show('materials')});$('#patientForm').onsubmit=e=>{e.preventDefault();const f=new FormData(e.target);const days=[...document.querySelectorAll('#dayPicker .day-btn.on')].map(b=>b.dataset.d);const customFields=[...document.querySelectorAll('#customList .custom-row')].map(r=>({label:r.querySelector('.cf-label').value.trim(),text:r.querySelector('.cf-text').value.trim()})).filter(c=>c.label||c.text);Object.assign(p,{name:f.get('name').trim(),address:f.get('address').trim(),phone:f.get('phone').trim(),recurrence:f.get('recurrence'),recurrenceDays:days,favorite:f.has('favorite'),notes:f.get('notes').trim(),dailyNote:f.get('dailyNote').trim(),nextHint:f.get('nextHint').trim(),birthDate:f.get('birthDate')||'',insurance:(f.get('insurance')||'').trim(),insuranceNumber:(f.get('insuranceNumber')||'').trim(),customFields});if(v)p.visit.used=[...new Set(f.getAll('used'))];if(fresh)state.patients.push(p);save('Patient gespeichert');d.close();renderAll();toast('Patient gespeichert')}}
  function openQuickMaterials(p){const quick=p.materials||[],all=state.materials.filter(m=>!m.archived).map(m=>m.name),rest=all.filter(n=>!quick.includes(n)),used=p.visit?.used||[];const chip=n=>`<label class="material-chip ${used.includes(n)?'on':''}"><input type="checkbox" name="used" value="${esc(n)}" ${used.includes(n)?'checked':''}><span class="chip-dot"></span>${esc(n)}</label>`;const moreBlock=rest.length?(quick.length?`<button type="button" id="toggleMoreMaterials" class="more-materials-toggle">＋ Weitere Materialien anzeigen</button><div class="chip-row" id="moreMaterials" hidden>${rest.map(chip).join('')}</div>`:`<p class="chip-label">Material auswählen</p><div class="chip-row">${rest.map(chip).join('')}</div>`):'';$('#modalContent').innerHTML=`<div class="modal-inner quick-material"><div class="quick-material-head"><span class="avatar">${initials(p.name)}</span><div><b>${esc(p.name)}</b>${p.visit?`<small>Besuch läuft seit ${new Date(p.visit.start).toLocaleTimeString('de-DE',{hour:'2-digit',minute:'2-digit'})}</small>`:''}</div></div>${quick.length?`<p class="chip-label">Häufig bei ${esc(p.name)}</p><div class="chip-row">${quick.map(chip).join('')}</div>`:''}${moreBlock}${!quick.length&&!rest.length?'<p class="empty">Noch kein Material im Lager angelegt.</p>':''}<div class="modal-actions"><button type="button" id="closeModal" class="btn secondary">Abbrechen</button><button type="button" id="saveQuickMaterial" class="btn">Speichern</button></div></div>`;const d=$('#modal');d.showModal();$('#closeModal').onclick=()=>d.close();$('#toggleMoreMaterials')?.addEventListener('click',()=>{$('#moreMaterials').hidden=false;$('#toggleMoreMaterials').remove()});$('#modalContent').querySelectorAll('input[name="used"]').forEach(cb=>cb.addEventListener('change',()=>cb.closest('.material-chip').classList.toggle('on',cb.checked)));$('#saveQuickMaterial').onclick=()=>{const checked=[...$('#modalContent').querySelectorAll('input[name="used"]:checked')].map(i=>i.value);p.visit??={start:Date.now(),used:[]};p.visit.used=checked;save('Material erfasst');d.close();renderAll();toast('Material gespeichert')}}
  function renderPatients(){const list=state.patients.filter(p=>state.showArchived?true:!p.archived).sort((a,b)=>Number(b.favorite)-Number(a.favorite)||a.name.localeCompare(b.name,'de'));$('#patients').innerHTML=`<div class="page-head"><div><p class="eyebrow">Stammdaten</p><h1>Patienten</h1><p>${list.length} Patienten sichtbar.</p></div><button id="addPatient" class="btn">＋ Patient hinzufügen</button></div><div class="panel"><div class="archive-toggle"><input id="archivePatientToggle" type="checkbox" ${state.showArchived?'checked':''}><label>Archivierte anzeigen</label></div><div class="filter-bar"><input id="patientFilter" placeholder="Patient, Notiz oder Besuch suchen …"></div><div id="allPatients" class="patient-list">${list.map(p=>`<div class="patient-row" data-id="${p.id}"><span class="favorite">${p.favorite?'★':'☆'}</span><span class="priority ${p.priority}"></span><span class="avatar">${initials(p.name)}</span><div class="patient-info"><b>${esc(p.name)}</b><small>${esc(p.dailyNote||p.notes||p.address||'')}</small></div><div class="row-actions"><button class="small-btn fav-p">★</button><button class="small-btn act-detail">Details</button><button class="small-btn archive-p">${p.archived?'Aktivieren':'Archivieren'}</button></div></div>`).join('')}</div></div>`;$('#addPatient').onclick=()=>openPatient();$('#archivePatientToggle').onchange=e=>{state.showArchived=e.target.checked;renderPatients()};$('#patientFilter').oninput=e=>filterRows($('#allPatients'),e.target.value);$('#allPatients').onclick=e=>{const r=e.target.closest('[data-id]');if(!r)return;const p=state.patients.find(x=>x.id===r.dataset.id);if(e.target.matches('.fav-p')){p.favorite=!p.favorite;save('Favorit geändert');renderPatients()}if(e.target.matches('.act-detail'))openPatient(p);if(e.target.matches('.archive-p')){p.archived=!p.archived;p.selected=false;save('Patient archiviert');renderAll()}}}
