  function openTourPrepare(){if(!active().length){$('#modalContent').innerHTML=`<div class="modal-inner modal-form"><h2>Keine Tour ausgewählt</h2><p>Für heute wurden noch keine Patienten ausgewählt.</p><div class="modal-actions"><button id="laterTour" class="btn secondary">❌ Später</button><button id="createTour" class="btn">📅 Tour erstellen</button></div></div>`;const d=$('#modal');d.showModal();$('#laterTour').onclick=()=>d.close();$('#createTour').onclick=()=>{d.close();show('dayplan')};return}$('#modalContent').innerHTML=`<div class="modal-inner modal-form"><h2>🚑 Tour vorbereiten</h2><p>Wie möchtest du deine heutige Tour planen?</p><div class="form-grid"><label class="full"><select id="tourMode" class="select"><option value="distance">🚗 Kürzeste Fahrstrecke</option><option value="own">✏️ Eigene Reihenfolge</option></select></label>${['Handy dabei','Material vollständig','Fahrzeugschlüssel dabei','Tour überprüft','Akku ausreichend geladen'].map(x=>`<label class="prep-check full"><input type="checkbox"> ${x}</label>`).join('')}<label class="full">Aktueller Kilometerstand (optional)<input id="tourStartKm" type="number" min="0" step="0.1" placeholder="z. B. 0"></label></div><div class="modal-actions"><button id="cancelTour" class="btn secondary">Abbrechen</button><button id="readyTour" class="btn">▶ Alles bereit – Tour starten</button></div></div>`;const d=$('#modal');d.showModal();$('#cancelTour').onclick=()=>d.close();$('#readyTour').onclick=()=>{const mode=$('#tourMode').value;if(mode==='distance')active().sort((a,b)=>(a.address||'').localeCompare(b.address||'')).forEach((p,i)=>p.order=i);const kmVal=$('#tourStartKm').value;if(kmVal!=='')recordKmStand(Math.max(0,Number(kmVal)||0),'','');state.tourStartedAt??=Date.now();save('Tour vorbereitet und gestartet');d.close();renderAll();show('dayplan');updateTourProgress();toast('Tour gestartet')}}
