  function startPlannedDay(){const entries=planEntries(planDate());if(entries.length){const byId=new Map(entries.map(e=>[e.id,e]));state.patients.forEach(p=>{const e=byId.get(p.id);p.selected=(Boolean(e)&&!p.archived)||(p.status==='active'&&!!p.visit);if(e){p.plannedMaterials=e.materials;p.dailyNote=e.note||p.dailyNote;p.priority=e.priority||p.priority}})}if(!active().length){toast('Bitte zuerst Patienten für heute planen.');openDayPlanModal(planDate());return}const begin=()=>{state.activeDayKey=planDate();state.tourStartedAt??=Date.now();state.dayClosed=false;save('Tagesmodus gestartet');renderAll();show('dayplan');toast('Tagesmodus gestartet')};if(state.tourStartedAt||state.kmStart?.[key()]!=null){begin();return}promptStartKm(begin)}
