    $('#dayplan').innerHTML=`<div class="mobile-tour-page"><div class="page-head"><div><p class="eyebrow">Tourplanung</p><h1>Ihre Tour für heute</h1><p>Tippen Sie auf „Besuch starten“ oder markieren Sie einen Besuch direkt als erledigt.</p></div><div class="tour-sort"><button id="sortDistance" class="btn secondary">Entfernung</button><button id="endTourNow" class="btn danger">■ Tour beenden</button></div></div>${suggestions.length?`<div class="recurring-suggestions"><b>🔁 Vorgeschlagene Besuche</b><p>${suggestions.map(p=>esc(p.name)).join(', ')}</p><button id="addRecurring" class="small-btn">Zur Tour hinzufügen</button></div>`:''}<div class="plan-grid"><div class="panel"><div class="section-head"><h2>Reihenfolge der Tour</h2><span class="status open">${list.length} Patienten</span></div><div id="tourList" class="tour-list-modern">${list.map(card).join('')||'<div class="empty">Keine Patienten ausgewählt.</div>'}</div></div><aside class="panel tour-km"><h2>Kilometer</h2><input id="kmInput" aria-label="Gefahrene Kilometer" type="number" min="0" step="0.1" value="${state.kilometers||0}" style="width:100%"><button id="saveKm" class="small-btn" style="margin-top:8px">Kilometer speichern</button></aside></div></div>`;
